'use strict'

const { test, after } = require('node:test')
const { equal } = require('node:assert')
const { createServer } = require('node:http')
const { once } = require('node:events')
const { Agent, request, interceptors } = require('../../')

// The dns and redirect interceptors rewrite opts.headers into the flat
// [key, value, key, value] form, so the cache interceptor must accept it no
// matter which side of the composition it ends up on.
// See https://github.com/nodejs/undici/issues/4470
test('cache interceptor accepts headers rewritten by the dns interceptor', async () => {
  const server = createServer((req, res) => {
    if (req.url === '/redirect') {
      res.writeHead(302, { location: '/' })
      res.end()
      return
    }

    res.writeHead(200, { 'cache-control': 'public, max-age=100' })
    res.end('hello')
  })

  server.listen(0)
  await once(server, 'listening')

  const origin = `http://localhost:${server.address().port}`

  const dnsThenCache = new Agent().compose(
    interceptors.dns(),
    interceptors.cache(),
    interceptors.redirect({ maxRedirections: 3 })
  )
  const cacheThenDns = new Agent().compose(
    interceptors.cache(),
    interceptors.dns(),
    interceptors.redirect({ maxRedirections: 3 })
  )

  after(async () => {
    server.close()
    await Promise.all([dnsThenCache.close(), cacheThenDns.close()])
  })

  for (const dispatcher of [dnsThenCache, cacheThenDns]) {
    // An empty array of headers, which the dns interceptor turns into
    // ['host', '<host>'].
    const response = await request(origin, { dispatcher, headers: [] })
    equal(response.statusCode, 200)
    equal(await response.body.text(), 'hello')

    // No headers at all, going through a redirect, which rebuilds the headers
    // as a flat array.
    const redirected = await request(`${origin}/redirect`, { dispatcher })
    equal(redirected.statusCode, 200)
    equal(await redirected.body.text(), 'hello')
  }
})

