    for (const [what, path, headers] of cases) {
      try {
        const r = await request(base + path, { dispatcher, headers })
        console.log(name, '|', what, '->', r.statusCode)
        r.body.destroy()
      } catch (e) {
        console.log(name, '|', what, '-> ERROR:', e.message)
      }
    }
  }
  server.close()
})
